import { Controller, Get, Logger, Post, Req, Res } from '@nestjs/common';
import { AppService } from './app.service';
import { DaprClient } from '@dapr/dapr';
import { Request, Response } from 'express';
import axios from 'axios';

const INPUT_BINDING_ROUTE =
  process.env.INPUT_BINDING_NAME || 'bindings-wip-dbo-shop-order-input-di';

const UNS_PUBSUB = process.env.UNS_PUBSUB || 'uns-pubsub-topic';

const DAPR_CHECK_URL =
  process.env.DAPR_CHECK_URL ?? 'http://localhost:3500/v1.0/healthz';

const CHECK_TIMEOUT_MS = process.env.CHECK_TIMEOUT_MS ?? '30000';

@Controller()
export class AppController {
  constructor(private readonly appService: AppService) {}

  @Get()
  getHello(): string {
    return this.appService.getHello();
  }

  @Get('health')
  async health(@Res() resp: Response): Promise<void> {
    try {
      const response = await axios.get(DAPR_CHECK_URL, {
        timeout: Number(CHECK_TIMEOUT_MS),
      });
      const statusCode = response.status;
      resp.status(200).json(`Status Code: ${statusCode}`);
    } catch (error) {
      const statusCode = error.response?.status ?? 'Unknown';

      if (statusCode !== 'Unknown') {
        const responseBody = error.response?.data ?? 'No response body';
        resp.status(500).json({ statusCode, responseBody });
        Logger.error(
          `Health check failed with status code: ${statusCode}, response body: ${responseBody}`,
        );
      } else {
        resp.status(500).json({});
        Logger.error(
          `Health check failed with error: ${error.message}`,
          error.stack,
        );
      }
    }
  }

  @Post(INPUT_BINDING_ROUTE)
  public async receiveEvent(@Req() request: Request): Promise<string> {
    Logger.log(`==============  Start =======================`);
    try {
      const sequenceNumber =
        request.headers['x-opt-sequence-number'] ||
        request.headers['X-Opt-Sequence-Number'];

      const event = JSON.parse(JSON.stringify(request.body));

      Logger.log(`Received event Time: ${event.__ts_ms}`);
      Logger.log(`SeqNum : ${sequenceNumber}`);
      Logger.log(`Received event: ${event.HANDLE}`);
      // const randomNumber = Math.floor(Math.random() * (5000 - 100 + 1)) + 100;
      // this.sleep(randomNumber);
      //throw new Error('Error Processing');
      return 'Event Received';
    } finally {
      Logger.log(`==============  END =======================`);
    }
  }

  @Post(UNS_PUBSUB)
  public async publishUns(@Req() request: Request): Promise<string> {
    Logger.log(`============== Start UNS Publishing =======================`);
    try {
      const status = request.body;
      Logger.log(`Publishing to pubsub: ${UNS_PUBSUB}, topic: downtime/status`);
      Logger.log(`Status payload: ${JSON.stringify(status)}`);

      const daprClient = new DaprClient();
      await daprClient.pubsub.publish(UNS_PUBSUB, `downtime/status`, status);

      Logger.log(`Successfully published status to UNS_PUBSUB`);
      return 'Status published successfully';
    } catch (error) {
      Logger.error(
        `Failed to publish to UNS_PUBSUB: ${error.message}`,
        error.stack,
      );
      throw new Error(`UNS publish failed: ${error.message}`);
    } finally {
      Logger.log(`============== END UNS Publishing =======================`);
    }
  }
  private sleep(ms: number): void {
    const start = Date.now();
    while (Date.now() - start < ms) {
      // Busy-wait loop to simulate synchronous sleep
    }
  }
}

